CREATE OR REPLACE FUNCTION public.prevent_buyer_workspace_change()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if old.workspace_id is distinct from new.workspace_id then
    raise exception 'buyer_workspace_id_immutable' using errcode = '42501';
