CREATE OR REPLACE FUNCTION public.reserve_property_intelligence_credit(p_workspace_id uuid, p_user_id uuid, p_operation_id text, p_plan_name text, p_normalized_address text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_period date := date_trunc('month', now())::date;
  v_limit integer := public.property_intelligence_plan_limit(p_plan_name);
  v_existing public.property_intelligence_lookup_operations%rowtype;
  v_balance public.property_intelligence_balances%rowtype;
  v_source text := null;
  v_operation_id uuid;
begin
  if p_workspace_id is null or p_user_id is null or coalesce(p_operation_id, '') = '' then
    return jsonb_build_object('ok', false, 'code', 'invalid_operation');
  end if;

  select * into v_existing
  from public.property_intelligence_lookup_operations
  where operation_id = p_operation_id;

  if found then
    return jsonb_build_object(
      'ok', v_existing.status in ('reserved', 'completed'),
      'operationId', v_existing.id,
      'status', v_existing.status,
      'creditSource', v_existing.credit_source,
      'alreadyReserved', true
    );
  end if;

  insert into public.property_intelligence_balances (
    workspace_id,
    billing_period_start,
    included_limit,
    included_used,
    purchased_available,
    purchased_used
  )
  values (p_workspace_id, v_period, v_limit, 0, 0, 0)
  on conflict (workspace_id) do update
    set billing_period_start = case
          when property_intelligence_balances.billing_period_start <> excluded.billing_period_start
            then excluded.billing_period_start
          else property_intelligence_balances.billing_period_start
        end,
        included_limit = excluded.included_limit,
        included_used = case
          when property_intelligence_balances.billing_period_start <> excluded.billing_period_start
            then 0
          else property_intelligence_balances.included_used
        end,
        updated_at = now()
  returning * into v_balance;

  if v_limit > 0 and v_balance.included_used < v_balance.included_limit then
    update public.property_intelligence_balances
    set included_used = included_used + 1,
        updated_at = now()
    where workspace_id = p_workspace_id
      and included_used < included_limit
    returning * into v_balance;
    if found then
      v_source := case when lower(coalesce(p_plan_name, '')) = 'owner admin' then 'owner_internal' else 'included' end;
    end if;
  end if;

  if v_source is null and (v_balance.purchased_available - v_balance.purchased_used) > 0 then
    update public.property_intelligence_balances
    set purchased_used = purchased_used + 1,
        updated_at = now()
    where workspace_id = p_workspace_id
      and (purchased_available - purchased_used) > 0
    returning * into v_balance;
    if found then
      v_source := 'purchased';
    end if;
  end if;

  if v_source is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'credits_exhausted',
      'includedLimit', v_balance.included_limit,
      'includedUsed', v_balance.included_used,
      'purchasedRemaining', greatest(0, v_balance.purchased_available - v_balance.purchased_used),
      'resetDate', (v_period + interval '1 month')::date
    );
  end if;

  insert into public.property_intelligence_lookup_operations (
    workspace_id,
    user_id,
    operation_id,
    normalized_address,
    plan_name,
    billing_period_start,
    status,
    credit_source,
    credit_charged
  )
  values (
    p_workspace_id,
    p_user_id,
    p_operation_id,
    p_normalized_address,
    p_plan_name,
    v_period,
    'reserved',
    v_source,
    true
  )
  returning id into v_operation_id;

  return jsonb_build_object(
    'ok', true,
    'operationId', v_operation_id,
    'creditSource', v_source,
    'includedLimit', v_balance.included_limit,
    'includedUsed', v_balance.included_used,
    'purchasedRemaining', greatest(0, v_balance.purchased_available - v_balance.purchased_used),
    'resetDate', (v_period + interval '1 month')::date
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_buyer_workspace_capacity()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  assigned_plan text;
  capacity_mode text;
  capacity_limit integer;
  buyer_limit integer;
  saved_count integer;
  purchased_capacity integer;
begin
  if new.workspace_id is null then
    raise exception 'buyer_workspace_required' using errcode = '23514';
  end if;

  select
    coalesce(effective_access_plan, current_plan, plan_name),
    coalesce(buyer_capacity_mode, 'finite'),
    buyer_capacity_limit,
    greatest(0, coalesce(purchased_buyer_capacity, 0))
    into assigned_plan, capacity_mode, capacity_limit, purchased_capacity
  from public.workspace_plan_assignments
  where workspace_id = new.workspace_id
  for update;

  if capacity_mode = 'unlimited' then
    return new;
  end if;

  if capacity_mode = 'custom' and capacity_limit is not null then
    buyer_limit := greatest(0, capacity_limit);
  else
    buyer_limit := public.dealblast_effective_buyer_limit(assigned_plan, purchased_capacity);
  end if;

  if buyer_limit is null then
    return new;
  end if;

  select count(*)
    into saved_count
  from public.buyers
  where workspace_id = new.workspace_id;

  if saved_count >= buyer_limit then
    raise exception 'buyer_plan_limit_exceeded' using errcode = '23514';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.prevent_account_profile_protected_updates()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  verified_email text := lower(coalesce(auth.jwt() ->> 'email', ''));
begin
  if auth.uid() is null then
    return new;
  end if;

  if new.user_id is distinct from old.user_id then
    raise exception 'user_id cannot be changed';
  end if;

  if new.role is distinct from old.role then
    raise exception 'role cannot be changed from account settings';
  end if;

  if new.account_status is distinct from old.account_status then
    raise exception 'account status cannot be changed from account settings';
  end if;

  if new.deactivated_at is distinct from old.deactivated_at then
    raise exception 'deactivation status cannot be changed from account settings';
  end if;

  if lower(coalesce(new.email, '')) is distinct from lower(coalesce(old.email, '')) then
    if verified_email = '' or lower(new.email) <> verified_email then
      raise exception 'email can only sync after Supabase Auth verifies the change';
    end if;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.assign_submission_workspace()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_workspace uuid;
begin
  if auth.uid() is not null
    and new.workspace_id is not null
    and public.can_access_inventory_workspace(new.workspace_id) then
    return new;
  end if;
  if (select count(*) from public.workspaces) = 1 then
    select id into v_workspace from public.workspaces limit 1;
    new.workspace_id := v_workspace;
  else
    raise exception 'A submission workspace route is required';
  end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.grant_property_intelligence_purchase(p_workspace_id uuid, p_purchase_id uuid, p_credits integer, p_stripe_event_id text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid;
begin
  if p_credits <= 0 then raise exception 'credits_must_be_positive'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_workspace_id::text, 0));
  insert into public.property_intelligence_credit_ledger
    (workspace_id, entry_type, credit_bucket, amount, purchase_id, stripe_event_id, idempotency_key, audit_reason)
  values (p_workspace_id, 'purchase_grant', 'purchased', p_credits, p_purchase_id, p_stripe_event_id,
    p_idempotency_key, 'verified_stripe_credit_pack_payment')
  on conflict (idempotency_key) do nothing returning id into v_id;
  if v_id is not null then
    update public.property_intelligence_addon_purchases set status='fulfilled', fulfilled_at=now(), fulfilled_ledger_entry_id=v_id
      where id=p_purchase_id and status <> 'fulfilled';
  end if;
  return jsonb_build_object('ok', true, 'granted', case when v_id is null then 0 else p_credits end, 'duplicate', v_id is null);
end $function$

CREATE OR REPLACE FUNCTION public.reserve_property_intelligence_credit_v2(p_workspace_id uuid, p_user_id uuid, p_operation_id text, p_plan_name text, p_normalized_address text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_existing public.property_intelligence_lookup_operations%rowtype; v_balance jsonb; v_bucket text; v_uuid uuid; v_expiry timestamptz;
begin
  if p_workspace_id is null or p_user_id is null or nullif(trim(p_operation_id), '') is null then
    return jsonb_build_object('ok', false, 'code', 'invalid_operation');
  end if;
  -- Serialize all balance decisions for the workspace; different operation IDs cannot overspend the final credit.
  perform pg_advisory_xact_lock(hashtextextended(p_workspace_id::text, 0));
  select * into v_existing from public.property_intelligence_lookup_operations where operation_id=p_operation_id for update;
  if found then return jsonb_build_object('ok', v_existing.status in ('reserved','completed'), 'operationId', v_existing.id,
    'status', v_existing.status, 'creditSource', v_existing.credit_source, 'alreadyReserved', true); end if;
  v_balance := public.property_intelligence_credit_balance(p_workspace_id);
  if (v_balance->>'includedRemaining')::integer > 0 then v_bucket := 'included';
  elsif (v_balance->>'purchasedRemaining')::integer > 0 then v_bucket := 'purchased';
  else return v_balance || jsonb_build_object('ok', false, 'code', 'credits_exhausted'); end if;
  if v_bucket='included' then
    select max(expires_at) into v_expiry from public.property_intelligence_credit_ledger
      where workspace_id=p_workspace_id and credit_bucket='included' and entry_type='included_grant' and expires_at>now();
  end if;
  insert into public.property_intelligence_lookup_operations
    (workspace_id,user_id,operation_id,normalized_address,plan_name,billing_period_start,status,credit_source,credit_charged)
  values (p_workspace_id,p_user_id,p_operation_id,p_normalized_address,p_plan_name,date_trunc('month',now())::date,'reserved',v_bucket,true)
  returning id into v_uuid;
  insert into public.property_intelligence_credit_ledger
    (workspace_id,entry_type,credit_bucket,amount,operation_id,expires_at,idempotency_key,audit_reason,created_by_user_id)
  values (p_workspace_id,'reservation',v_bucket,-1,p_operation_id,v_expiry,'pi:reserve:'||p_operation_id,'property_intelligence_provider_reservation',p_user_id);
  return public.property_intelligence_credit_balance(p_workspace_id) || jsonb_build_object('ok',true,'operationId',v_uuid,'creditSource',v_bucket);
end $function$

CREATE OR REPLACE FUNCTION public.release_property_intelligence_credit_v2(p_operation_uuid uuid, p_failure_code text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_op public.property_intelligence_lookup_operations%rowtype; v_expiry timestamptz;
begin
  select * into v_op from public.property_intelligence_lookup_operations where id=p_operation_uuid for update;
  if not found or v_op.status <> 'reserved' then return; end if;
  select expires_at into v_expiry from public.property_intelligence_credit_ledger where idempotency_key='pi:reserve:'||v_op.operation_id;
  insert into public.property_intelligence_credit_ledger
    (workspace_id,entry_type,credit_bucket,amount,operation_id,expires_at,idempotency_key,audit_reason)
  values (v_op.workspace_id,'release',v_op.credit_source,1,v_op.operation_id,v_expiry,'pi:release:'||v_op.operation_id,
    coalesce(nullif(p_failure_code,''),'provider_failure')) on conflict (idempotency_key) do nothing;
  update public.property_intelligence_lookup_operations set status='released',credit_charged=false,failure_code=p_failure_code,
    completed_at=now(),updated_at=now() where id=p_operation_uuid and status='reserved';
end $function$

CREATE OR REPLACE FUNCTION public.adjust_property_intelligence_purchased_credits(p_workspace_id uuid, p_requested_debit integer, p_entry_type text, p_idempotency_key text, p_reason text, p_stripe_event_id text DEFAULT NULL::text, p_created_by_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_balance jsonb; v_available integer; v_debit integer; v_id uuid;
begin
  if p_requested_debit <= 0 or p_entry_type not in ('refund','dispute','admin_correction') then raise exception 'invalid_credit_adjustment'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_workspace_id::text,0));
  if exists(select 1 from public.property_intelligence_credit_ledger where idempotency_key=p_idempotency_key) then
    return jsonb_build_object('ok',true,'duplicate',true,'adjusted',0);
  end if;
  v_balance := public.property_intelligence_credit_balance(p_workspace_id);
  v_available := greatest(0,(v_balance->>'purchasedRemaining')::integer);
  v_debit := least(v_available,p_requested_debit);
  if v_debit <= 0 then return jsonb_build_object('ok',true,'adjusted',0,'balanceProtected',true); end if;
  insert into public.property_intelligence_credit_ledger
    (workspace_id,entry_type,credit_bucket,amount,stripe_event_id,idempotency_key,audit_reason,created_by_user_id)
  values (p_workspace_id,p_entry_type,'purchased',-v_debit,p_stripe_event_id,p_idempotency_key,p_reason,p_created_by_user_id)
  returning id into v_id;
  return jsonb_build_object('ok',true,'adjusted',v_debit,'ledgerEntryId',v_id,'balanceProtected',v_debit<p_requested_debit);
end $function$

CREATE OR REPLACE FUNCTION public.admin_adjust_property_intelligence_credits(p_workspace_id uuid, p_amount integer, p_credit_bucket text, p_entry_type text, p_idempotency_key text, p_reason text, p_created_by_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_balance jsonb;
  v_available integer;
  v_id uuid;
begin
  if p_workspace_id is null or p_amount = 0 or nullif(trim(p_reason), '') is null then
    raise exception 'invalid_credit_adjustment';
  end if;
  if p_credit_bucket not in ('included', 'purchased') then raise exception 'invalid_credit_bucket'; end if;
  if p_entry_type not in ('promotion', 'admin_correction', 'refund') then raise exception 'invalid_credit_entry_type'; end if;
  if p_entry_type = 'refund' and p_credit_bucket <> 'purchased' then raise exception 'refund_requires_purchased_bucket'; end if;

  perform pg_advisory_xact_lock(hashtextextended(p_workspace_id::text, 0));
  if exists(select 1 from public.property_intelligence_credit_ledger where idempotency_key = p_idempotency_key) then
    return public.property_intelligence_credit_balance(p_workspace_id) || jsonb_build_object('ok', true, 'duplicate', true, 'adjusted', 0);
  end if;

  v_balance := public.property_intelligence_credit_balance(p_workspace_id);
  v_available := case p_credit_bucket
    when 'included' then (v_balance->>'includedRemaining')::integer
    else (v_balance->>'purchasedRemaining')::integer
  end;
  if p_amount < 0 and v_available < abs(p_amount) then
    return v_balance || jsonb_build_object('ok', false, 'code', 'negative_balance_prevented', 'adjusted', 0);
  end if;

  insert into public.property_intelligence_credit_ledger
    (workspace_id, entry_type, credit_bucket, amount, idempotency_key, audit_reason, created_by_user_id, metadata)
  values
    (p_workspace_id, p_entry_type, p_credit_bucket, p_amount, p_idempotency_key, p_reason, p_created_by_user_id,
     jsonb_build_object('source', 'owner_admin_credit_operations'))
  returning id into v_id;

  return public.property_intelligence_credit_balance(p_workspace_id)
    || jsonb_build_object('ok', true, 'duplicate', false, 'adjusted', p_amount, 'ledgerEntryId', v_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.grant_property_intelligence_included_credits(p_workspace_id uuid, p_plan_name text, p_period_start date, p_period_end date, p_idempotency_key text, p_enterprise_limit integer DEFAULT NULL::integer, p_reason text DEFAULT 'plan_cycle_grant'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_limit integer;
  v_already_granted integer;
  v_grant integer;
  v_id uuid;
begin
  if p_workspace_id is null or p_period_start is null or p_period_end is null or p_period_end <= p_period_start then
    raise exception 'invalid_credit_grant_period';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_workspace_id::text || ':' || p_period_start::text, 0));

  if exists(select 1 from public.property_intelligence_credit_ledger where idempotency_key = p_idempotency_key) then
    return jsonb_build_object('ok', true, 'granted', 0, 'duplicate', true);
  end if;

  v_limit := public.property_intelligence_included_limit(p_plan_name, p_enterprise_limit);
  select coalesce(sum(amount), 0)::integer into v_already_granted
  from public.property_intelligence_credit_ledger
  where workspace_id = p_workspace_id
    and entry_type = 'included_grant'
    and credit_bucket = 'included'
    and billing_period_start = p_period_start
    and billing_period_end = p_period_end;

  v_grant := greatest(0, v_limit - greatest(0, v_already_granted));
  if v_grant <= 0 then
    return jsonb_build_object(
      'ok', true,
      'granted', 0,
      'duplicate', false,
      'allowance', v_limit,
      'alreadyGranted', v_already_granted,
      'reason', case when v_limit <= 0 then 'plan_has_no_included_credits' else 'cycle_allowance_already_satisfied' end
    );
  end if;

  insert into public.property_intelligence_credit_ledger
    (workspace_id, entry_type, credit_bucket, amount, billing_period_start, billing_period_end,
     expires_at, idempotency_key, audit_reason, metadata)
  values
    (p_workspace_id, 'included_grant', 'included', v_grant, p_period_start, p_period_end,
     p_period_end::timestamptz, p_idempotency_key, p_reason,
     jsonb_build_object('planName', p_plan_name, 'cycleAllowance', v_limit, 'priorCycleGrants', v_already_granted))
  returning id into v_id;

  return jsonb_build_object(
    'ok', true,
    'granted', v_grant,
    'duplicate', false,
    'ledgerEntryId', v_id,
    'allowance', v_limit,
    'alreadyGranted', v_already_granted
  );
end
$function$
